import{_ as a,o as n,c as t,a2 as e}from"./chunks/framework.B4hAkGey.js";const g=JSON.parse('{"title":"16.1 基础入门：UDP 之上的握手与加密","description":"","frontmatter":{},"headers":[],"relativePath":"guide/16-handwritten-dtls-srtp/basics.md","filePath":"guide/16-handwritten-dtls-srtp/basics.md","lastUpdated":1792683941000}'),p={name:"guide/16-handwritten-dtls-srtp/basics.md"};function l(o,s,i,r,d,c){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_16-1-基础入门-udp-之上的握手与加密" tabindex="-1">16.1 基础入门：UDP 之上的握手与加密 <a class="header-anchor" href="#_16-1-基础入门-udp-之上的握手与加密" aria-label="Permalink to &quot;16.1 基础入门：UDP 之上的握手与加密&quot;">​</a></h1><blockquote><p>WebRTC 强制要求所有媒体流必须加密传输，这是写进 RFC 的硬规定（RFC 8827）。但媒体走的是 UDP，而 TLS 依赖 TCP 的可靠有序特性——于是就有了 DTLS：把 TLS 的握手和密码学原封不动搬到 UDP 上，再叠加一层 SRTP 给每个 RTP 包做加密和认证。本章讲清楚这两个协议是什么、为什么需要、以及它们如何协同。</p></blockquote><hr><h2 id="_16-1-1-为什么-udp-上还要握手" tabindex="-1">16.1.1 为什么 UDP 上还要握手 <a class="header-anchor" href="#_16-1-1-为什么-udp-上还要握手" aria-label="Permalink to &quot;16.1.1 为什么 UDP 上还要握手&quot;">​</a></h2><p>WebRTC 的安全模型有一条<strong>不可协商的红线</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  所有媒体（音频/视频）必须加密，没有&quot;明文模式&quot;开关      │</span></span>
<span class="line"><span>│  —— RFC 8827 (WebRTC Security Architecture)         │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><p>为什么不能像传统直播（RTMP/HLS）那样允许明文？因为 WebRTC 是<strong>浏览器原生 API</strong>：</p><ul><li>浏览器是<strong>第三方代码运行环境</strong>，网页 JS 可以拿到媒体流</li><li>如果媒体是明文，恶意网页可以悄悄把摄像头画面转发到任何服务器</li><li>P2P 通信跨越不可信网络（咖啡店 Wi-Fi、运营商骨干网），窃听成本极低</li></ul><p>所以 WebRTC 规定：<strong>媒体加密使用 DTLS-SRTP，且密钥必须由通信双方直接协商（DTLS 握手），不能经过信令服务器传递</strong>。即使信令服务器被攻破，攻击者也无法解密媒体内容——这叫<strong>端到端加密（End-to-End Encryption, E2EE）</strong> 的基础形态。</p><p>但问题来了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>媒体走 UDP 的原因：</span></span>
<span class="line"><span>  - 低延迟（TCP 重传会卡画面）</span></span>
<span class="line"><span>  - 容忍丢包（丢一帧比等重传好）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TLS 不能跑在 UDP 上的原因：</span></span>
<span class="line"><span>  - 握手依赖可靠传输（丢一个握手包整个流程卡死）</span></span>
<span class="line"><span>  - 加密记录依赖有序到达（TLS 用隐式序列号计算 MAC）</span></span>
<span class="line"><span>  - 没有 TCP 的&quot;连接&quot;概念，无法防简单的源地址欺骗</span></span></code></pre></div><p>解法就是 <strong>DTLS（Datagram Transport Layer Security，数据报传输层安全协议）</strong>：RFC 6347 定义，本质上就是&quot;能跑在 UDP 上的 TLS&quot;。</p><hr><h2 id="_16-1-2-dtls-tls-over-udp-解决重传与乱序" tabindex="-1">16.1.2 DTLS = TLS over UDP：解决重传与乱序 <a class="header-anchor" href="#_16-1-2-dtls-tls-over-udp-解决重传与乱序" aria-label="Permalink to &quot;16.1.2 DTLS = TLS over UDP：解决重传与乱序&quot;">​</a></h2><p>DTLS 1.2 对应 TLS 1.2，DTLS 1.3 对应 TLS 1.3。它针对 UDP 的三个缺陷各打了一剂补丁：</p><table tabindex="0"><thead><tr><th>UDP 的缺陷</th><th>DTLS 的补丁</th><th>机制</th></tr></thead><tbody><tr><td>丢包不重传</td><td><strong>握手重传定时器</strong></td><td>每个握手消息发送后启动定时器，超时未收到对方下一条消息就重发</td></tr><tr><td>包乱序到达</td><td><strong>epoch + sequence number</strong></td><td>每条记录显式携带 16-bit epoch + 48-bit 序列号，接收方按序号重组</td></tr><tr><td>无连接、易伪造</td><td><strong>Cookie 机制（HelloVerifyRequest）</strong></td><td>服务器先验证客户端 IP 可达，再分配资源</td></tr></tbody></table><h3 id="cookie-机制-防-dos-的第一道门" tabindex="-1">Cookie 机制：防 DoS 的第一道门 <a class="header-anchor" href="#cookie-机制-防-dos-的第一道门" aria-label="Permalink to &quot;Cookie 机制：防 DoS 的第一道门&quot;">​</a></h3><p>UDP 最大的安全隐患是<strong>源地址伪造（IP Spoofing）</strong>：攻击者可以用受害者的 IP 作为源地址向服务器发送 ClientHello，服务器如果直接分配状态并回复大量数据，就成了放大攻击（Amplification Attack）的帮凶。</p><p>DTLS 的应对（借鉴自 SCTP）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                                    服务器</span></span>
<span class="line"><span>  │                                        │</span></span>
<span class="line"><span>  │ ── ClientHello (无 cookie) ──────────&gt; │</span></span>
<span class="line"><span>  │                                        │ 服务器不分配状态，</span></span>
<span class="line"><span>  │                                        │ 只生成一个 cookie</span></span>
<span class="line"><span>  │ &lt;── HelloVerifyRequest (含 cookie) ─── │ (通常是 HMAC(客户端IP, 密钥))</span></span>
<span class="line"><span>  │                                        │ 【无状态，可丢弃】</span></span>
<span class="line"><span>  │                                        │</span></span>
<span class="line"><span>  │ ── ClientHello (带回 cookie) ────────&gt; │ 验证 cookie 有效 → 才分配状态</span></span>
<span class="line"><span>  │                                        │ 证明客户端确实持有该 IP</span></span>
<span class="line"><span>  │ &lt;── ServerHello ────────────────────── │</span></span>
<span class="line"><span>  │              ...继续完整握手...          │</span></span></code></pre></div><p><strong>关键点</strong>：HelloVerifyRequest 阶段服务器<strong>完全无状态</strong>——cookie 是用服务器私有密钥对客户端 IP 做 HMAC 算出来的，服务器不需要存任何东西，收到带回 cookie 的 ClientHello 时重新算一遍对比即可。伪造了源 IP 的攻击者收不到 cookie，自然无法完成第二步。</p><h3 id="epoch-与-sequence-number-给每条记录编号" tabindex="-1">epoch 与 sequence number：给每条记录编号 <a class="header-anchor" href="#epoch-与-sequence-number-给每条记录编号" aria-label="Permalink to &quot;epoch 与 sequence number：给每条记录编号&quot;">​</a></h3><p>TLS 的记录层用隐式序列号（双方各自维护计数器），这要求 TCP 保证有序。DTLS 改为<strong>显式编号</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DTLS 记录头 (13 字节)：</span></span>
<span class="line"><span>┌──────────┬─────────┬──────────────┬──────────────────┬──────────┐</span></span>
<span class="line"><span>│  type    │ version │    epoch     │ sequence_number  │  length  │</span></span>
<span class="line"><span>│ (1 byte) │(2 bytes)│  (2 bytes)   │    (6 bytes)     │ (2 bytes)│</span></span>
<span class="line"><span>└──────────┴─────────┴──────────────┴──────────────────┴──────────┘</span></span></code></pre></div><ul><li><strong>epoch（纪元）</strong>：每完成一次 ChangeCipherSpec（切换加密套件），epoch 加 1。<code>epoch=0</code> 是明文握手，<code>epoch=1</code> 是加密后的应用数据</li><li><strong>sequence_number</strong>：每个 epoch 内从 0 开始递增的 48 位序号</li></ul><p>有了显式编号，乱序到达的记录可以被重新排序，重复的记录可以被丢弃——可靠性由 DTLS 自己保障，不再依赖下层传输协议。</p><hr><h2 id="_16-1-3-dtls-握手全流程" tabindex="-1">16.1.3 DTLS 握手全流程 <a class="header-anchor" href="#_16-1-3-dtls-握手全流程" aria-label="Permalink to &quot;16.1.3 DTLS 握手全流程&quot;">​</a></h2><p>WebRTC 中 DTLS 握手的完整消息流（RFC 6347 + RFC 5763）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 (Controlling)                          服务器 (Controlled)</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ ──── 1. ClientHello ───────────────────────&gt; │   支持套件列表、random、扩展</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ &lt;──── 2. HelloVerifyRequest ──────────────── │   下发 cookie（防伪造）</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ ──── 3. ClientHello (含 cookie) ───────────&gt; │   证明 IP 可达</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ &lt;──── 4. ServerHello ─────────────────────── │   选定套件、server random</span></span>
<span class="line"><span>   │ &lt;──── 5. Certificate ─────────────────────── │   自签名证书（WebRTC 不用 CA）</span></span>
<span class="line"><span>   │ &lt;──── 6. ServerKeyExchange ───────────────── │   ECDHE 公钥参数</span></span>
<span class="line"><span>   │ &lt;──── 7. ServerHelloDone ─────────────────── │   服务器发完了</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ ──── 8. ClientKeyExchange ─────────────────&gt; │   客户端 ECDHE 公钥</span></span>
<span class="line"><span>   │ ──── 9. ChangeCipherSpec ──────────────────&gt; │   &quot;下一条起加密&quot;</span></span>
<span class="line"><span>   │ ──── 10. Finished ─────────────────────────&gt; │   全部握手消息的 MAC 校验</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ &lt;──── 11. ChangeCipherSpec ───────────────── │   服务器也切加密</span></span>
<span class="line"><span>   │ &lt;──── 12. Finished ───────────────────────── │   双向验证完成</span></span>
<span class="line"><span>   │                                              │</span></span>
<span class="line"><span>   │ ═══════ SRTP 加密媒体开始传输 ════════════════ │</span></span></code></pre></div><p>每条消息的关键载荷：</p><table tabindex="0"><thead><tr><th>消息</th><th>核心内容</th><th>作用</th></tr></thead><tbody><tr><td>ClientHello</td><td>client_random、密码套件列表、<code>use_srtp</code> 扩展</td><td>发起协商，声明支持的 SRTP Profile</td></tr><tr><td>HelloVerifyRequest</td><td>cookie</td><td>无状态防 DoS</td></tr><tr><td>Certificate</td><td>X.509 自签名证书</td><td>提供身份公钥（配合 SDP 指纹认证，见进阶篇）</td></tr><tr><td>ServerKeyExchange</td><td>ECDHE 服务器公钥 + 签名</td><td>前向保密的密钥交换参数</td></tr><tr><td>ClientKeyExchange</td><td>ECDHE 客户端公钥</td><td>双方各自算出 pre-master secret</td></tr><tr><td>Finished</td><td>此前所有握手消息的 verify_data（MAC）</td><td>防中间人篡改握手过程</td></tr></tbody></table><p><strong>与 HTTPS 握手的两个显著不同</strong>：</p><ol><li><strong>证书是自签名的</strong>。WebRTC 不使用 CA 体系——浏览器为每次通话临时生成证书。身份认证不靠 CA 签名链，而是靠 <strong>SDP 中的 <code>a=fingerprint</code> 指纹</strong>（信令通道传递，假设信令安全）。</li><li><strong>必须协商 <code>use_srtp</code> 扩展</strong>（RFC 5764）。这个扩展告诉对方：&quot;握手完成后，我们要从这次 DTLS 会话里导出 SRTP 密钥&quot;，并声明支持的 SRTP 加密套件（如 <code>SRTP_AES128_CM_HMAC_SHA1_80</code>）。</li></ol><hr><h2 id="_16-1-4-srtp-给每个-rtp-包上锁" tabindex="-1">16.1.4 SRTP：给每个 RTP 包上锁 <a class="header-anchor" href="#_16-1-4-srtp-给每个-rtp-包上锁" aria-label="Permalink to &quot;16.1.4 SRTP：给每个 RTP 包上锁&quot;">​</a></h2><p>DTLS 握手完成后，双方并不直接用 DTLS 记录层传媒体（那样每个包要多付 DTLS 记录头开销）。而是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DTLS 握手 ──导出密钥──&gt; SRTP 会话密钥</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>RTP 包 ──&gt; SRTP protect ──&gt; SRTP 包 ──&gt; UDP 发送</span></span>
<span class="line"><span>           (加密+认证)</span></span></code></pre></div><p><strong>SRTP（Secure Real-time Transport Protocol，安全实时传输协议）</strong>，RFC 3711 定义，专为 RTP 设计的轻量级加密方案：</p><table tabindex="0"><thead><tr><th>组件</th><th>算法</th><th>作用</th></tr></thead><tbody><tr><td><strong>加密</strong></td><td>AES-CM（AES Counter Mode，计数器模式）</td><td>把 RTP payload 加密成密文，<strong>RTP 头保持明文</strong>（中间设备仍需读 SSRC/seq）</td></tr><tr><td><strong>认证</strong></td><td>HMAC-SHA1</td><td>对整个 SRTP 包（含明文头）计算认证标签，防篡改</td></tr><tr><td><strong>密钥管理</strong></td><td>SRTP KDF（Key Derivation Function）</td><td>从一份 master key 派生出加密密钥、认证密钥、盐值</td></tr></tbody></table><p>SRTP 包的结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────┬──────────────────────┬─────────┬──────────────┐</span></span>
<span class="line"><span>│   RTP 头(明文)    │  加密的 RTP payload   │ MKI(可选)│  Auth Tag    │</span></span>
<span class="line"><span>│   12+ 字节        │   (AES-CM 密文)       │         │ HMAC-SHA1    │</span></span>
<span class="line"><span>│                  │                      │         │ 80 或 32 bit │</span></span>
<span class="line"><span>└──────────────────┴──────────────────────┴─────────┴──────────────┘</span></span>
<span class="line"><span>   └──────────────┬──────────────────────────────┘</span></span>
<span class="line"><span>                  └── HMAC-SHA1 的输入（全部认证）──┘</span></span></code></pre></div><p>为什么用 AES 计数器模式（Counter Mode）而不是 CBC？</p><ul><li><strong>随机访问</strong>：每个包用独立的计数器块加密，丢包不影响后续包解密（CBC 会连锁失败）</li><li><strong>无需填充</strong>：CTR 是流密码模式，不产生填充字节，不膨胀包大小</li><li><strong>可并行</strong>：加解密都只需要 AES 加密函数</li></ul><hr><h2 id="_16-1-5-密钥导出-rfc-5764-exporter" tabindex="-1">16.1.5 密钥导出：RFC 5764 Exporter <a class="header-anchor" href="#_16-1-5-密钥导出-rfc-5764-exporter" aria-label="Permalink to &quot;16.1.5 密钥导出：RFC 5764 Exporter&quot;">​</a></h2><p>DTLS 握手结束后，双方各自持有相同的 master secret。SRTP 需要的密钥材料通过 <strong>TLS Exporter</strong> 机制导出（RFC 5705 / RFC 5764）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keying_material = TLS-Exporter(</span></span>
<span class="line"><span>    label  = &quot;EXTRACTOR-dtls_srtp&quot;,   ← 固定的标识字符串</span></span>
<span class="line"><span>    context = &quot;&quot;,                      ← WebRTC 中为空</span></span>
<span class="line"><span>    length  = 2 * (master_key_len + master_salt_len)</span></span>
<span class="line"><span>            = 2 * (16 + 14) = 60 字节  ← AES-128 时</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>导出的 60 字节按固定顺序切分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字节偏移  0        16            30       46            60</span></span>
<span class="line"><span>         ├─────────┼──────────────┼─────────┼──────────────┤</span></span>
<span class="line"><span>         │ client  │   client     │ server  │   server     │</span></span>
<span class="line"><span>         │ master  │  master salt │ master  │ master salt  │</span></span>
<span class="line"><span>         │ key(16B)│    (14B)     │ key(16B)│    (14B)     │</span></span>
<span class="line"><span>         └─────────┴──────────────┴─────────┴──────────────┘</span></span>
<span class="line"><span>              └─ 客户端用它加密自己发的包 ─┘</span></span>
<span class="line"><span>              └─ 服务器用它加密自己发的包 ─┘</span></span></code></pre></div><p>注意是<strong>双向各一份</strong>：客户端用自己的 master key/salt 加密发出的 SRTP，服务器用另一份。双方都知道两份密钥，所以都能解密对方的包，但加密方向严格分离——这避免了两个方向使用相同密钥导致的计数器冲突。</p><p>拿到 master key/salt 之后，还要经过 <strong>SRTP KDF</strong> 派生出真正干活的 session key（会话密钥），这部分细节留到进阶篇。</p><hr><h2 id="_16-1-6-小结" tabindex="-1">16.1.6 小结 <a class="header-anchor" href="#_16-1-6-小结" aria-label="Permalink to &quot;16.1.6 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th></tr></thead><tbody><tr><td>为什么强制加密</td><td>WebRTC 跑在浏览器里，明文媒体=隐私灾难</td></tr><tr><td>DTLS</td><td>TLS 的 UDP 移植版：重传定时器 + epoch/seq 编号 + cookie 防伪造</td></tr><tr><td>HelloVerifyRequest</td><td>服务器无状态验证客户端 IP 真实性，防放大攻击</td></tr><tr><td>Finished</td><td>对全部握手消息做 MAC，防中间人篡改协商结果</td></tr><tr><td>SRTP</td><td>AES-CM 加密 payload + HMAC-SHA1 认证整包，RTP 头保留明文</td></tr><tr><td>Exporter</td><td>DTLS 握手产物，label 固定为 <code>&quot;EXTRACTOR-dtls_srtp&quot;</code>，导出双向各 30 字节</td></tr></tbody></table><p>下一章我们拆开密钥派生的内部：证书指纹怎么验证、SRTP KDF 怎么从一份 master key 变出三把钥匙、ROC 和滑动窗口如何防重放。</p><p>→ <a href="./advanced">16.2 进阶应用：证书指纹、密钥导出与 SRTP KDF</a></p>`,57)])])}const u=a(p,[["render",l]]);export{g as __pageData,u as default};
